1	package com.example.starter.cems;
2	
3	import java.math.BigDecimal;
4	import java.sql.Timestamp;
5	import java.time.Duration;
6	import java.time.LocalDateTime;
7	import java.time.format.DateTimeFormatter;
8	import java.time.temporal.ChronoUnit;
9	import java.util.ArrayList;
10	import java.util.LinkedHashMap;
11	import java.util.List;
12	import java.util.Map;
13	import java.util.function.Supplier;
14	
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.annotation.Transactional;
17	
18	import com.example.starter.cems.CemsTypes.ArchiveOutletRequest;
19	import com.example.starter.cems.CemsTypes.ArchiveResult;
20	import com.example.starter.cems.CemsTypes.ConfirmOrderRequest;
21	import com.example.starter.cems.CemsTypes.DailyEvalRequest;
22	import com.example.starter.cems.CemsTypes.DailyEvalResult;
23	import com.example.starter.cems.CemsTypes.GapCheckRequest;
24	import com.example.starter.cems.CemsTypes.GapResult;
25	import com.example.starter.cems.CemsTypes.HourlyReadingRequest;
26	import com.example.starter.cems.CemsTypes.HourlyReadingResult;
27	import com.example.starter.cems.CemsTypes.OrderView;
28	import com.example.starter.cems.CemsTypes.OutletView;
29	import com.example.starter.cems.CemsTypes.Receipt;
30	import com.example.starter.cems.CemsTypes.RecomputeRequest;
31	import com.example.starter.cems.CemsTypes.RecomputeResult;
32	import com.example.starter.cems.CemsTypes.RegisterOutletRequest;
33	import com.example.starter.cems.CemsTypes.ReleaseRestrictionRequest;
34	import com.example.starter.cems.CemsTypes.ReleaseResult;
35	
36	/**
37	 * 核心业务服务：许可登记→在线监测→超标标记→限排执行→复测解除→归档。
38	 * 所有多表写操作均在同一事务内完成；边界判定一律“含本值达标 / 恰满触发”。
39	 */
40	@Service
41	public class CemsService {
42	
43	    /** 连续小时超标触发限排令的次数：恰连续 3 次触发。 */
44	    static final int RESTRICTION_STREAK = 3;
45	    /** 确认执行期限（小时）：恰满 2 小时未确认即升级。 */
46	    static final long CONFIRM_DEADLINE_HOURS = 2;
47	    /** 数据缺失督办阈值（分钟）：严格大于 120 分钟才督办，恰 120 分钟不标记。 */
48	    static final long GAP_THRESHOLD_MINUTES = 120;
49	    /** 升级时联动限产比例：限产 30%。 */
50	    static final BigDecimal ESCALATION_CUT_RATIO = new BigDecimal("0.30");
51	
52	    private static final DateTimeFormatter ORDER_HOUR_FMT = DateTimeFormatter.ofPattern("yyyyMMddHH");
53	
54	    private final CemsRepository repo;
55	    private final CemsClock clock;
56	    private final IdempotencySupport idem;
57	
58	    public CemsService(CemsRepository repo, CemsClock clock, IdempotencySupport idem) {
59	        this.repo = repo;
60	        this.clock = clock;
61	        this.idem = idem;
62	    }
63	
64	    // ---------------- 许可登记 ----------------
65	
66	    @Transactional
67	    public OutletView registerOutlet(RegisterOutletRequest req) {
68	        Map<String, Object> fields = new LinkedHashMap<>();
69	        fields.put("outletCode", req.outletCode());
70	        fields.put("outletName", req.outletName());
71	        fields.put("dailyLimit", req.dailyLimit());
72	        fields.put("hourlyLimit", req.hourlyLimit());
73	        fields.put("unit", req.unit());
74	        return replayable(req.requestId(), "REGISTER", fields, OutletView.class, () -> doRegister(req));
75	    }
76	
77	    private OutletView doRegister(RegisterOutletRequest req) {
78	        String code = requireText(req.outletCode(), "outletCode");
79	        String name = requireText(req.outletName(), "outletName");
80	        requireNonNullNonNegative(req.dailyLimit(), "dailyLimit");
81	        requireNonNullNonNegative(req.hourlyLimit(), "hourlyLimit");
82	        if (repo.findOutlet(code) != null) {
83	            throw new ConflictException("排口已登记: " + code);
84	        }
85	        String unit = req.unit() == null || req.unit().isBlank() ? "mg/L" : req.unit();
86	        LocalDateTime now = clock.now();
87	        repo.insertOutlet(code, name, req.dailyLimit(), req.hourlyLimit(), unit, now);
88	        repo.insertEvent(code, "REGISTER", now, false,
89	                "dailyLimit=" + req.dailyLimit() + ",hourlyLimit=" + req.hourlyLimit());
90	        return toOutletView(repo.findOutlet(code));
91	    }
92	
93	    // ---------------- 日均值评价 ----------------
94	
95	    @Transactional
96	    public DailyEvalResult evaluateDaily(DailyEvalRequest req) {
97	        if (req.day() == null) {
98	            throw new IllegalArgumentException("day 不能为空");
99	        }
100	        Map<String, Object> fields = new LinkedHashMap<>();
101	        fields.put("outletCode", req.outletCode());
102	        fields.put("day", req.day().toString());
103	        fields.put("avgValue", req.avgValue());
104	        return replayable(req.requestId(), "DAILY_EVAL", fields, DailyEvalResult.class, () -> doEvaluateDaily(req));
105	    }
106	
107	    private DailyEvalResult doEvaluateDaily(DailyEvalRequest req) {
108	        String code = requireText(req.outletCode(), "outletCode");
109	        requireNonNullNonNegative(req.avgValue(), "avgValue");
110	        Map<String, Object> outlet = loadOutlet(code);
111	        BigDecimal dailyLimit = bd(outlet.get("daily_limit"));
112	        LocalDateTime dayStart = req.day().atStartOfDay();
113	        LocalDateTime dayEnd = dayStart.plusDays(1);
114	        LocalDateTime now = clock.now();
115	
116	        if (isArchived(outlet)) {
117	            // 归档为终态：迟到监测数据只记迟到事件，不参与评价、不改变排口状态。
118	            repo.insertEvent(code, "LATE_READING", now, true,
119	                    "DAY " + req.day() + " avgValue=" + req.avgValue());
120	            return new DailyEvalResult(req.requestId(), code, req.day(), req.avgValue(),
121	                    dailyLimit, false, true, null);
122	        }
123	
124	        repo.markMonitoring(code, now);
125	        boolean fresh = repo.insertDailyReading(code, dayStart, req.avgValue(), now);
126	        if (!fresh) {
127	            Map<String, Object> existingReadings = repo.findDailyReadings(code).stream()
128	                    .filter(r -> dayStart.equals(lt(r.get("period_start"))))
129	                    .findFirst().orElse(null);
130	            if (existingReadings != null && req.avgValue().compareTo(bd(existingReadings.get("avg_value"))) != 0) {
131	                throw new ConflictException("排口＋日期读数已存在且数值不同: " + code + " " + req.day());
132	            }
133	        }
134	        boolean exceeded = req.avgValue().compareTo(dailyLimit) > 0;
135	        Long markId = null;
136	        Map<String, Object> mark = repo.findDailyMark(code, dayStart);
137	        if (exceeded && mark == null) {
138	            markId = repo.insertMark(code, "DAILY_AVG", dayStart, dayEnd, dailyLimit, req.avgValue(),
139	                    0, req.requestId(), "ACTIVE", now);
140	            repo.insertEvent(code, "MARK", now, false,
141	                    "DAILY_AVG actual=" + req.avgValue() + " limit=" + dailyLimit);
142	        } else if (mark != null) {
143	            markId = ((Number) mark.get("id")).longValue();
144	        }
145	        if (fresh) {
146	            repo.insertEvent(code, "READING", now, false,
147	                    "DAY " + req.day() + " avgValue=" + req.avgValue());
148	        }
149	        return new DailyEvalResult(req.requestId(), code, req.day(), req.avgValue(),
150	                dailyLimit, exceeded, false, markId);
151	    }
152	
153	    // ---------------- 小时均值上报与连续超标链 ----------------
154	
155	    @Transactional
156	    public HourlyReadingResult reportHourly(HourlyReadingRequest req) {
157	        String code = requireText(req.outletCode(), "outletCode");
158	        requireNonNullNonNegative(req.avgValue(), "avgValue");
159	        if (req.hour() == null) {
160	            throw new IllegalArgumentException("hour 不能为空");
161	        }
162	        LocalDateTime hour = req.hour().truncatedTo(ChronoUnit.HOURS);
163	        Map<String, Object> outlet = loadOutlet(code);
164	        BigDecimal hourlyLimit = bd(outlet.get("hourly_limit"));
165	        LocalDateTime now = clock.now();
166	
167	        if (isArchived(outlet)) {
168	            repo.insertEvent(code, "LATE_READING", now, true,
169	                    "HOUR " + hour + " avgValue=" + req.avgValue());
170	            return new HourlyReadingResult(code, hour, req.avgValue(), hourlyLimit,
171	                    false, false, true, 0, false, null, null);
172	        }
173	
174	        repo.markMonitoring(code, now);
175	        boolean fresh = repo.insertHourlyReading(code, hour, req.avgValue(), now);
176	        if (!fresh) {
177	            // 排口＋时段去重：重复上报不重复评价、不重复触发限排。
178	            Map<String, Object> mark = repo.findHourlyMark(code, hour);
179	            Map<String, Object> occupying = repo.findOccupyingOrder(code);
180	            return new HourlyReadingResult(code, hour, req.avgValue(), hourlyLimit,
181	                    true, mark != null, false, mark == null ? 0 : ((Number) mark.get("chain_index")).intValue(),
182	                    false, occupying == null ? null : (String) occupying.get("order_no"),
183	                    occupying == null ? null : (String) occupying.get("status"));
184	        }
185	        repo.insertEvent(code, "READING", now, false, "HOUR " + hour + " avgValue=" + req.avgValue());
186	
187	        List<ChainPoint> chain = rebuildHourlyChain(code, hourlyLimit);
188	        ChainPoint current = chain.stream().filter(p -> p.hour().equals(hour)).findFirst().orElseThrow();
189	
190	        String orderNo = null;
191	        String orderStatus = null;
192	        boolean triggered = false;
193	        if (current.streak() == RESTRICTION_STREAK
194	                && repo.findOrderByTrigger(code, hour) == null
195	                && repo.findOccupyingOrder(code) == null) {
196	            orderNo = issueOrder(code, hour, hourlyLimit, now);
197	            orderStatus = "PENDING_CONFIRM";
198	            triggered = true;
199	        }
200	        if (triggered) {
201	            repo.updateOutletStatus(code, "RESTRICTED", now);
202	            repo.insertEvent(code, "ORDER_ISSUED", now, false,
203	                    "orderNo=" + orderNo + " triggerHour=" + hour);
204	        } else {
205	            Map<String, Object> occupying = repo.findOccupyingOrder(code);
206	            if (occupying != null) {
207	                orderNo = (String) occupying.get("order_no");
208	                orderStatus = (String) occupying.get("status");
209	            }
210	        }
211	        return new HourlyReadingResult(code, hour, req.avgValue(), hourlyLimit,
212	                false, current.exceeded(), false, current.streak(), triggered, orderNo, orderStatus);
213	    }
214	
215	    private String issueOrder(String code, LocalDateTime triggerHour, BigDecimal hourlyLimit, LocalDateTime now) {
216	        String orderNo = "RO-" + code + "-" + triggerHour.format(ORDER_HOUR_FMT);
217	        LocalDateTime deadline = now.plusHours(CONFIRM_DEADLINE_HOURS);
218	        repo.insertOrder(orderNo, code, triggerHour, now, deadline, code);
219	        return orderNo;
220	    }
221	
222	    /**
223	     * 按全部小时读数重算连续超标链并重建小时标记：恰连续 3 次（链序号=3）为触发点。
224	     * 相邻整点、逐时连续且均超标才累计链序号；任一合格读数或中间缺测都使链重置。
225	     * 已随限排令复测合格而解除（RESOLVED）的历史标记，复算后仍保持 RESOLVED。
226	     */
227	    private List<ChainPoint> rebuildHourlyChain(String code, BigDecimal hourlyLimit) {
228	        List<Map<String, Object>> readings = repo.findHourlyReadings(code);
229	        Map<String, String> priorStatus = new LinkedHashMap<>();
230	        for (Map<String, Object> m : repo.findHourlyMarks(code)) {
231	            priorStatus.put(lt(m.get("period_start")).toString(), (String) m.get("status"));
232	        }
233	        List<ChainPoint> points = new ArrayList<>();
234	        LocalDateTime prevHour = null;
235	        int streak = 0;
236	        for (Map<String, Object> r : readings) {
237	            LocalDateTime hour = lt(r.get("period_start"));
238	            boolean exceeded = bd(r.get("avg_value")).compareTo(hourlyLimit) > 0;
239	            if (exceeded) {
240	                streak = (prevHour != null && hour.equals(prevHour.plusHours(1)) && streak > 0)
241	                        ? streak + 1 : 1;
242	            } else {
243	                streak = 0;
244	            }
245	            points.add(new ChainPoint(hour, exceeded, streak));
246	            prevHour = hour;
247	        }
248	        repo.deleteHourlyMarks(code);
249	        LocalDateTime now = clock.now();
250	        for (ChainPoint p : points) {
251	            if (p.exceeded()) {
252	                BigDecimal value = readings.stream()
253	                        .filter(r -> p.hour().equals(lt(r.get("period_start"))))
254	                        .map(r -> bd(r.get("avg_value"))).findFirst().orElseThrow();
255	                String markStatus = "RESOLVED".equals(priorStatus.get(p.hour().toString()))
256	                        ? "RESOLVED" : "ACTIVE";
257	                repo.insertMark(code, "HOURLY_AVG", p.hour(), p.hour().plusHours(1),
258	                        hourlyLimit, value, p.streak(), null, markStatus, now);
259	            }
260	        }
261	        return points;
262	    }
263	
264	    // ---------------- 连续缺失督办 ----------------
265	
266	    @Transactional
267	    public GapResult checkGap(GapCheckRequest req) {
268	        String code = requireText(req.outletCode(), "outletCode");
269	        if (req.missingFrom() == null || req.missingTo() == null) {
270	            throw new IllegalArgumentException("missingFrom/missingTo 不能为空");
271	        }
272	        if (!req.missingTo().isAfter(req.missingFrom())) {
273	            throw new IllegalArgumentException("missingTo 必须晚于 missingFrom");
274	        }
275	        Map<String, Object> outlet = loadOutlet(code);
276	        if (isArchived(outlet)) {
277	            throw new ConflictException("排口已归档（终态），不再督办数据缺失: " + code);
278	        }
279	        long minutes = Duration.between(req.missingFrom(), req.missingTo()).toMinutes();
280	        boolean marked = minutes > GAP_THRESHOLD_MINUTES;
281	        LocalDateTime now = clock.now();
282	        if (marked) {
283	            boolean created = repo.insertGap(code, req.missingFrom(), req.missingTo(),
284	                    (int) minutes, "SUPERVISED", now);
285	            if (created) {
286	                repo.insertEvent(code, "GAP_SUPERVISE", now, false,
287	                        "gap=" + minutes + "min [" + req.missingFrom() + "," + req.missingTo() + ")");
288	            }
289	        }
290	        return new GapResult(code, req.missingFrom(), req.missingTo(), minutes, marked,
291	                marked ? now : null);
292	    }
293	
294	    // ---------------- 限排令确认执行（基数冻结同事务） ----------------
295	
296	    @Transactional
297	    public Receipt confirmOrder(ConfirmOrderRequest req) {
298	        Map<String, Object> fields = new LinkedHashMap<>();
299	        fields.put("orderNo", req.orderNo());
300	        return replayable(req.requestId(), "CONFIRM", fields, Receipt.class, () -> doConfirm(req));
301	    }
302	
303	    private Receipt doConfirm(ConfirmOrderRequest req) {
304	        String orderNo = requireText(req.orderNo(), "orderNo");
305	        Map<String, Object> order = loadOrder(orderNo);
306	        String code = (String) order.get("outlet_code");
307	        Map<String, Object> outlet = loadOutlet(code);
308	        if (isArchived(outlet)) {
309	            throw new ConflictException("排口已归档，不能再确认限排令: " + code);
310	        }
311	        String status = (String) order.get("status");
312	        LocalDateTime now = clock.now();
313	        return switch (status) {
314	            case "CLOSED" -> throw new ConflictException("限排令已关闭，不能重复确认: " + orderNo);
315	            case "ACTIVE" -> throw new ConflictException("限排令已确认执行: " + orderNo);
316	            case "ESCALATED" -> throw new ConflictException("限排令已超期升级，不能再确认: " + orderNo);
317	            default -> {
318	                LocalDateTime deadline = lt(order.get("confirm_deadline"));
319	                if (!now.isBefore(deadline)) {
320	                    throw new ConflictException("已超过确认执行期限（恰满2小时），限排令应升级: " + orderNo);
321	                }
322	                // 限排生效与排放总量冻结基数在同一 UPDATE/同一事务内完成，不存在“生效而基数未定”。
323	                BigDecimal frozenQty = repo.sumHourlyValuesUpTo(code, now);
324	                int n = repo.confirmOrder(orderNo, frozenQty, now);
325	                if (n == 0) {
326	                    throw new ConflictException("限排令状态已变化，确认未受理: " + orderNo);
327	                }
328	                repo.updateOutletStatus(code, "RESTRICTED", now);
329	                repo.insertEvent(code, "CONFIRM", now, false,
330	                        "orderNo=" + orderNo + " frozenTotalQty=" + frozenQty);
331	                yield new Receipt(req.requestId(), "CONFIRM_RESTRICTION", false);
332	            }
333	        };
334	    }
335	
336	    // ---------------- 超时升级并联动限产 ----------------
337	
338	    @Transactional
339	    public List<OrderView> escalateSweep(String outletCode) {
340	        Map<String, Object> outlet = loadOutlet(outletCode);
341	        if (isArchived(outlet)) {
342	            throw new ConflictException("排口已归档: " + outletCode);
343	        }
344	        List<OrderView> escalated = new ArrayList<>();
345	        LocalDateTime now = clock.now();
346	        for (Map<String, Object> order : repo.findPendingConfirmOrders(outletCode)) {
347	            String orderNo = (String) order.get("order_no");
348	            LocalDateTime deadline = lt(order.get("confirm_deadline"));
349	            if (!now.isBefore(deadline)) {
350	                BigDecimal frozenQty = repo.sumHourlyValuesUpTo(outletCode, now);
351	                int n = repo.escalateOrder(orderNo, frozenQty, now);
352	                if (n > 0) {
353	                    // 升级与联动限产同事务：升级提交则限产记录必然存在。
354	                    repo.insertProductionCut(orderNo, outletCode, ESCALATION_CUT_RATIO,
355	                            "限排令下达后恰满2小时未确认，联动限产30%", now);
356	                    repo.updateOutletStatus(outletCode, "RESTRICTED", now);
357	                    repo.insertEvent(outletCode, "ESCALATE", now, false,
358	                            "orderNo=" + orderNo + " cutRatio=" + ESCALATION_CUT_RATIO);
359	                    escalated.add(toOrderView(repo.findOrder(orderNo)));
360	                }
361	            }
362	        }
363	        return escalated;
364	    }
365	
366	    // ---------------- 复测合格解除（关闭同事务） ----------------
367	
368	    @Transactional
369	    public ReleaseResult release(ReleaseRestrictionRequest req) {
370	        Map<String, Object> fields = new LinkedHashMap<>();
371	        fields.put("orderNo", req.orderNo());
372	        fields.put("retestHour", req.retestHour() == null ? null : req.retestHour().toString());
373	        fields.put("retestValue", req.retestValue());
374	        return replayable(req.requestId(), "RELEASE", fields, ReleaseResult.class, () -> doRelease(req));
375	    }
376	
377	    private ReleaseResult doRelease(ReleaseRestrictionRequest req) {
378	        String orderNo = requireText(req.orderNo(), "orderNo");
379	        requireNonNullNonNegative(req.retestValue(), "retestValue");
380	        if (req.retestHour() == null) {
381	            throw new IllegalArgumentException("retestHour 不能为空");
382	        }
383	        Map<String, Object> order = loadOrder(orderNo);
384	        String code = (String) order.get("outlet_code");
385	        Map<String, Object> outlet = loadOutlet(code);
386	        if (isArchived(outlet)) {
387	            throw new ConflictException("排口已归档，不能解除限排令: " + code);
388	        }
389	        String status = (String) order.get("status");
390	        BigDecimal hourlyLimit = bd(outlet.get("hourly_limit"));
391	        LocalDateTime retestHour = req.retestHour().truncatedTo(ChronoUnit.HOURS);
392	        LocalDateTime now = clock.now();
393	        return switch (status) {
394	            case "CLOSED" -> throw new ConflictException("限排令已关闭: " + orderNo);
395	            case "PENDING_CONFIRM" -> throw new ConflictException("限排令尚未确认执行，不能解除: " + orderNo);
396	            default -> {
397	                // 复测合格：含本值达标；不合格不得解除，限排令状态不变。
398	                if (req.retestValue().compareTo(hourlyLimit) > 0) {
399	                    throw new ConflictException("复测小时均值 " + req.retestValue()
400	                            + " 超过限值 " + hourlyLimit + "，复测不合格，不能解除限排");
401	                }
402	                LocalDateTime issuedAt = lt(order.get("issued_at"));
403	                if (!retestHour.isAfter(issuedAt.truncatedTo(ChronoUnit.HOURS))) {
404	                    throw new IllegalArgumentException("复测时段必须晚于限排令下达时段");
405	                }
406	                boolean freshRetest = repo.insertHourlyReading(code, retestHour, req.retestValue(), now);
407	                if (!freshRetest) {
408	                    Map<String, Object> existing = repo.findHourlyReadings(code).stream()
409	                            .filter(r -> retestHour.equals(lt(r.get("period_start"))))
410	                            .findFirst().orElse(null);
411	                    if (existing != null && req.retestValue().compareTo(bd(existing.get("avg_value"))) != 0) {
412	                        throw new ConflictException("复测时段读数已存在且数值不同: " + retestHour);
413	                    }
414	                }
415	                // 解除限排与限排令关闭在同一事务：任一失败整体回滚。
416	                int n = repo.closeOrder(orderNo, retestHour, retestHour.plusHours(1),
417	                        req.retestValue(), req.requestId(), now);
418	                if (n == 0) {
419	                    throw new ConflictException("限排令状态已变化，解除未受理: " + orderNo);
420	                }
421	                repo.resolveActiveHourlyMarks(code);
422	                repo.updateOutletStatus(code, "MONITORING", now);
423	                repo.insertEvent(code, "RELEASE", now, false,
424	                        "orderNo=" + orderNo + " retestValue=" + req.retestValue());
425	                yield new ReleaseResult(req.requestId(), orderNo, code, "CLOSED", now);
426	            }
427	        };
428	    }
429	
430	    // ---------------- 归档（终态、重复幂等） ----------------
431	
432	    @Transactional
433	    public ArchiveResult archive(ArchiveOutletRequest req) {
434	        Map<String, Object> fields = new LinkedHashMap<>();
435	        fields.put("outletCode", req.outletCode());
436	        return replayable(req.requestId(), "ARCHIVE", fields, ArchiveResult.class, () -> doArchive(req));
437	    }
438	
439	    private ArchiveResult doArchive(ArchiveOutletRequest req) {
440	        String code = requireText(req.outletCode(), "outletCode");
441	        Map<String, Object> outlet = loadOutlet(code);
442	        LocalDateTime archivedAt = isArchived(outlet)
443	                ? lt(outlet.get("archived_at")) : clock.now();
444	        if (isArchived(outlet)) {
445	            // 归档为终态：重复归档返回幂等成功，不重复写事件、不改变状态。
446	            return new ArchiveResult(req.requestId(), code, false, archivedAt);
447	        }
448	        if (repo.findOccupyingOrder(code) != null) {
449	            throw new ConflictException("存在执行中限排令，须复测解除后方可归档: " + code);
450	        }
451	        int n = repo.archiveOutlet(code, archivedAt);
452	        if (n == 0) {
453	            throw new ConflictException("排口状态已变化，归档未受理: " + code);
454	        }
455	        repo.insertEvent(code, "ARCHIVE", archivedAt, false, "排口归档（终态）");
456	        return new ArchiveResult(req.requestId(), code, true, archivedAt);
457	    }
458	
459	    // ---------------- 复算 ----------------
460	
461	    @Transactional
462	    public RecomputeResult recompute(RecomputeRequest req) {
463	        String code = requireText(req.outletCode(), "outletCode");
464	        Map<String, Object> outlet = loadOutlet(code);
465	        if (isArchived(outlet)) {
466	            throw new ConflictException("排口已归档（终态），不能复算: " + code);
467	        }
468	        BigDecimal hourlyLimit = bd(outlet.get("hourly_limit"));
469	        BigDecimal dailyLimit = bd(outlet.get("daily_limit"));
470	        List<String> details = new ArrayList<>();
471	
472	        // 1) 小时超标链标记重建，并对缺失的触发限排记录做补建（不改变既有令状态）。
473	        List<ChainPoint> chain = rebuildHourlyChain(code, hourlyLimit);
474	        int orderCreated = 0;
475	        for (ChainPoint p : chain) {
476	            if (p.streak() == RESTRICTION_STREAK && repo.findOrderByTrigger(code, p.hour()) == null) {
477	                if (repo.findOccupyingOrder(code) == null) {
478	                    String orderNo = issueOrder(code, p.hour(), hourlyLimit, clock.now());
479	                    orderCreated++;
480	                    details.add("补建限排令 " + orderNo + "（触发时段 " + p.hour() + "）");
481	                } else {
482	                    details.add("触发时段 " + p.hour() + " 存在执行中限排令，跳过补建");
483	                }
484	            }
485	        }
486	
487	        // 2) 日均超标标记按日读数重建（保留原标记携带的 requestId）。
488	        Map<String, String> dailyRequestByPeriod = new LinkedHashMap<>();
489	        for (Map<String, Object> m : repo.findDailyMarks(code)) {
490	            Object rid = m.get("request_id");
491	            dailyRequestByPeriod.put(lt(m.get("period_start")).toString(), rid == null ? null : rid.toString());
492	        }
493	        int dailyMarkCount = 0;
494	        repo.deleteDailyMarks(code);
495	        LocalDateTime now = clock.now();
496	        for (Map<String, Object> r : repo.findDailyReadings(code)) {
497	            LocalDateTime dayStart = lt(r.get("period_start"));
498	            BigDecimal value = bd(r.get("avg_value"));
499	            if (value.compareTo(dailyLimit) > 0) {
500	                repo.insertMark(code, "DAILY_AVG", dayStart, dayStart.plusDays(1), dailyLimit, value,
501	                        0, dailyRequestByPeriod.get(dayStart.toString()), "ACTIVE", now);
502	                dailyMarkCount++;
503	            }
504	        }
505	
506	        // 3) 缺失督办按首末读数之间的连续整点缺槽重算：仅连续缺槽严格大于 2 小时才督办。
507	        repo.deleteGaps(code);
508	        int gapCount = rebuildGaps(code, details);
509	
510	        long activeOrderCount = repo.findOrders(code).stream()
511	                .filter(o -> !"CLOSED".equals(o.get("status"))).count();
512	        int hourlyMarkCount = (int) chain.stream().filter(ChainPoint::exceeded).count();
513	        return new RecomputeResult(code, hourlyMarkCount, dailyMarkCount, (int) activeOrderCount,
514	                gapCount, details);
515	    }
516	
517	    /**
518	     * 依据小时读数序列找出连续缺失整点区间，缺失严格大于 2 小时（&gt;120 分钟）才重新登记督办。
519	     */
520	    private int rebuildGaps(String code, List<String> details) {
521	        List<Map<String, Object>> readings = repo.findHourlyReadings(code);
522	        if (readings.size() < 2) {
523	            return 0;
524	        }
525	        int gapCount = 0;
526	        LocalDateTime now = clock.now();
527	        for (int i = 1; i < readings.size(); i++) {
528	            LocalDateTime prev = lt(readings.get(i - 1).get("period_start"));
529	            LocalDateTime cur = lt(readings.get(i).get("period_start"));
530	            long missingHours = ChronoUnit.HOURS.between(prev, cur) - 1;
531	            if (missingHours > 0) {
532	                LocalDateTime gapStart = prev.plusHours(1);
533	                LocalDateTime gapEnd = cur;
534	                long minutes = Duration.between(gapStart, gapEnd).toMinutes();
535	                if (minutes > GAP_THRESHOLD_MINUTES) {
536	                    repo.insertGap(code, gapStart, gapEnd, (int) minutes, "SUPERVISED", now);
537	                    gapCount++;
538	                    details.add("复算缺失督办 " + minutes + " 分钟 [" + gapStart + "," + gapEnd + ")");
539	                }
540	            }
541	        }
542	        return gapCount;
543	    }
544	
545	    // ---------------- 查询 ----------------
546	
547	    @Transactional(readOnly = true)
548	    public OutletView getOutlet(String code) {
549	        return toOutletView(loadOutlet(code));
550	    }
551	
552	    @Transactional(readOnly = true)
553	    public OrderView getOrder(String orderNo) {
554	        return toOrderView(loadOrder(orderNo));
555	    }
556	
557	    @Transactional(readOnly = true)
558	    public List<Map<String, Object>> getEvents(String code) {
559	        loadOutlet(code);
560	        return repo.findEvents(code);
561	    }
562	
563	    // ---------------- 幂等支撑 ----------------
564	
565	    /**
566	     * 幂等执行：指纹覆盖 requestId 与全部业务字段。
567	     * 同键同参返回首次结果；同键异参抛 409 且不执行动作、不改变排口状态。
568	     * 先插入占位行（主键串行化同键并发），业务动作成功后回写结果；动作失败则随事务回滚释放该键。
569	     */
570	    private <T> T replayable(String requestId, String requestType, Map<String, Object> fields,
571	                             Class<T> resultType, Supplier<T> action) {
572	        String rid = requireText(requestId, "requestId");
573	        String fingerprint = idem.fingerprint(rid, fields);
574	        Map<String, Object> existing = repo.findIdempotent(rid);
575	        if (existing != null) {
576	            return replayOrConflict(rid, fingerprint, existing, resultType);
577	        }
578	        while (true) {
579	            if (repo.insertIdempotent(rid, requestType, fingerprint, "", clock.now())) {
580	                T result = action.get();
581	                repo.updateIdempotentResult(rid, idem.toJson(result));
582	                return result;
583	            }
584	            // 同键并发：等待首个事务提交结果；若其回滚（占位行消失）则重新抢占。
585	            Map<String, Object> raced = waitForIdempotentResult(rid);
586	            if (raced != null) {
587	                return replayOrConflict(rid, fingerprint, raced, resultType);
588	            }
589	        }
590	    }
591	
592	    private <T> T replayOrConflict(String rid, String fingerprint, Map<String, Object> row, Class<T> resultType) {
593	        if (!fingerprint.equals(row.get("fingerprint"))) {
594	            throw new ConflictException("requestId=" + rid + " 请求参数与首次调用不一致（409 幂等冲突）");
595	        }
596	        return idem.fromJson((String) row.get("result_json"), resultType);
597	    }
598	
599	    /**
600	     * 并发同键后等待首个事务提交结果（真实并发协调，带超时）。
601	     * @return 已回写结果的幂等行；占位行消失（首个事务回滚）时返回 null 供调用方重新抢占
602	     */
603	    private Map<String, Object> waitForIdempotentResult(String rid) {
604	        long deadlineMillis = System.currentTimeMillis() + 15_000L;
605	        while (true) {
606	            Map<String, Object> row = repo.findIdempotent(rid);
607	            if (row == null) {
608	                return null;
609	            }
610	            if (!"".equals(row.get("result_json"))) {
611	                return row;
612	            }
613	            if (System.currentTimeMillis() >= deadlineMillis) {
614	                throw new ConflictException("requestId=" + rid + " 并发请求等待首次结果超时");
615	            }
616	            try {
617	                Thread.sleep(20L);
618	            } catch (InterruptedException e) {
619	                Thread.currentThread().interrupt();
620	                throw new ConflictException("并发幂等等待被中断");
621	            }
622	        }
623	    }
624	
625	    // ---------------- 公共辅助 ----------------
626	
627	    private Map<String, Object> loadOutlet(String code) {
628	        Map<String, Object> outlet = repo.findOutlet(code);
629	        if (outlet == null) {
630	            throw new NotFoundException("排口不存在: " + code);
631	        }
632	        return outlet;
633	    }
634	
635	    private Map<String, Object> loadOrder(String orderNo) {
636	        Map<String, Object> order = repo.findOrder(orderNo);
637	        if (order == null) {
638	            throw new NotFoundException("限排令不存在: " + orderNo);
639	        }
640	        return order;
641	    }
642	
643	    private boolean isArchived(Map<String, Object> outlet) {
644	        return "ARCHIVED".equals(outlet.get("status"));
645	    }
646	
647	    private static BigDecimal bd(Object value) {
648	        if (value == null) {
649	            return null;
650	        }
651	        return value instanceof BigDecimal b ? b : new BigDecimal(value.toString());
652	    }
653	
654	    private static LocalDateTime lt(Object value) {
655	        if (value == null) {
656	            return null;
657	        }
658	        return value instanceof Timestamp t ? t.toLocalDateTime() : LocalDateTime.parse(value.toString());
659	    }
660	
661	    private static String requireText(String value, String field) {
662	        if (value == null || value.isBlank()) {
663	            throw new IllegalArgumentException(field + " 不能为空");
664	        }
665	        return value;
666	    }
667	
668	    private static void requireNonNullNonNegative(BigDecimal value, String field) {
669	        if (value == null) {
670	            throw new IllegalArgumentException(field + " 不能为空");
671	        }
672	        if (value.signum() < 0) {
673	            throw new IllegalArgumentException(field + " 不能为负数");
674	        }
675	    }
676	
677	    private static OutletView toOutletView(Map<String, Object> o) {
678	        return new OutletView(
679	                (String) o.get("outlet_code"),
680	                (String) o.get("outlet_name"),
681	                (String) o.get("status"),
682	                bd(o.get("daily_limit")),
683	                bd(o.get("hourly_limit")),
684	                (String) o.get("limit_unit"),
685	                lt(o.get("created_at")),
686	                lt(o.get("archived_at")));
687	    }
688	
689	    private static OrderView toOrderView(Map<String, Object> o) {
690	        return new OrderView(
691	                (String) o.get("order_no"),
692	                (String) o.get("outlet_code"),
693	                (String) o.get("status"),
694	                bd(o.get("frozen_total_qty")),
695	                lt(o.get("issued_at")),
696	                lt(o.get("confirm_deadline")),
697	                lt(o.get("confirmed_at")),
698	                lt(o.get("escalated_at")),
699	                (String) o.get("escalate_reason"),
700	                bd(o.get("retest_value")),
701	                lt(o.get("closed_at")));
702	    }
703	
704	    /** 小时连续超标链上的一个计算点。 */
705	    private record ChainPoint(LocalDateTime hour, boolean exceeded, int streak) {
706	    }
707	}
