private record Eval(String status, Integer permitVersion) {}

private Eval evaluate(boolean overflowFlag, BigDecimal rainfall, Map<String,Object> permit, LocalDateTime hour) {
    if (!overflowFlag) return new Eval("NORMAL", permit == null ? null : versionOf(permit));
    Integer pv = permit == null ? null : versionOf(permit);
    if (rainfall == null) return new Eval("PENDING_REVIEW", pv);
    if (permit == null) return new Eval("NON_COMPLIANT", null);
    LocalDateTime validFrom = lt(permit.get("valid_from"));
    LocalDateTime validTo = lt(permit.get("valid_to"));
    boolean inWindow = !hour.isBefore(validFrom) && !hour.plusHours(1).isAfter(validTo);
    if (!inWindow) return new Eval("NON_COMPLIANT", pv);
    if (rainfall.compareTo(bd(permit.get("min_rainfall"))) < 0) return new Eval("NON_COMPLIANT", pv);
    return new Eval("COMPLIANT", pv);
}
