private OverflowPermitView doUpsertPermit(OverflowPermitRequest req) {
    String code = requireText(req.outletCode(), "outletCode");
    Map<String,Object> outlet = loadOutlet(code); // 404
    if (archived) throw 422
    if (req.expectedVersion() == null || req.expectedVersion() < 0) throw 400 "expectedVersion 不能为空且不小于0"
    if (req.validFrom() == null || req.validTo() == null) throw 400
    if (!req.validFrom().isBefore(req.validTo())) throw 400 "validFrom 必须早于 validTo（UTC 半开窗口）"
    requireNonNullNonNegative(req.minRainfall(), "minRainfall");
    if (req.maxConsecutiveHours() == null || req.maxConsecutiveHours() < 1) throw 400
    int current = overflowRepo.currentPermitVersion(code);
    if (req.expectedVersion() != current)
        throw new ConflictException("溢流许可版本冲突: expectedVersion=" + req.expectedVersion() + ", 当前版本=" + current);
    int newVersion = current + 1;
    try {
        overflowRepo.insertPermit(code, newVersion, req.validFrom(), req.validTo(), req.minRainfall(), req.maxConsecutiveHours(), clock.now());
    } catch (DuplicateKeyException e) {
        throw new ConflictException("溢流许可版本并发冲突: version=" + newVersion);
    }
    return toPermitView(overflowRepo.findPermitByVersion(code, newVersion));
}
