            if (compliant) segment.add(row);
        }
        prev = row;
    }
    anomalies.addAll(finishSegment(code, segment));
    return anomalies;
}

private List<OverflowAnomalyView> finishSegment(String code, List<Map<String,Object>> segment) {
    if (segment.isEmpty()) return List.of();
    Integer pv = permitVersionOf(segment.get(0));
    Map<String,Object> permit = pv == null ? null : overflowRepo.findPermitByVersion(code, pv);
    int max = permit == null ? 0 : ((Number) permit.get("max_consecutive_hours")).intValue();
    if (segment.size() <= max) return List.of();
    LocalDateTime start = lt(segment.get(0).get("hour_start"));
    LocalDateTime end = lt(segment.get(segment.size()-1).get("hour_start")).plusHours(1);
    overflowRepo.insertAnomaly(code, start, end, segment.size(), max, clock.now());
    return List.of(new OverflowAnomalyView(start, end, segment.size(), max));
}
